  function generateProfile(){
  var decs=data.decisions,total=decs.length;
  if(total<2||profileGenerating)return;
  profileGenerating=true;profileError=false;if(currentPage==='dashboard'&&document.getElementById('boardShell'))bdRenderDash();else render();
  fetch(CLAUDE_API_URL,{
  method:'POST',
  headers:{'Content-Type':'application/json'},
  body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:3000,messages:[{role:'user',content:buildAssessPrompt()}]})
  }).then(function(r){return r.json()}).then(function(j){
  var text='';
  if(j.content){for(var ci=0;ci<j.content.length;ci++)if(j.content[ci].text)text+=j.content[ci].text}
  var parsed=JSON.parse(text.replace(/```json|```/g,'').trim());
  var ks=['outcomes_principles','scrutiny_trust','decisive_deliberative','broad_defined','candor_diplomatic'];
  var sc={};for(var ki=0;ki<ks.length;ki++){var v=Number(parsed.scores[ks[ki]]);if(isNaN(v))throw new Error('score '+ks[ki]);sc[ks[ki]]=Math.max(0,Math.min(100,Math.round(v)))}
  if(typeof parsed.profile!=='string'||parsed.profile.indexOf('STRENGTHS')<0)throw new Error('profile shape');
  data.profile={text:parsed.profile,scores:sc,generatedAt:Date.now(),decisionCount:total,drillCount:Object.keys(data.drills||{}).filter(function(k){var r=data.drills[k];return r&&(r.instinct||r.caseAgainst||r.verdict)}).length};
  profileGenerating=false;
  saveData();if(currentPage==='dashboard'&&document.getElementById('boardShell'))bdRenderDash();else render();
  }).catch(function(err){
  console.error('Assessment error:',err);
  profileGenerating=false;profileError=true;if(currentPage==='dashboard'&&document.getElementById('boardShell'))bdRenderDash();else render();
  });
  }

