  on('assessBegin',function(){assessStep=1;if(!data.assessment)data.assessment={answers:{},scores:{},completedAt:null};bdRenderAssess()});
  if(assessQTimer){clearInterval(assessQTimer);assessQTimer=null}
  if(assessStep>=1&&assessStep<=10&&document.getElementById('qTimerTx')){var qtRemain=15;
  assessQTimer=setInterval(function(){var el=document.getElementById('qTimerTx');
  if(!el){clearInterval(assessQTimer);assessQTimer=null;return} /* self-clearing: the element leaves with the page; the tick never touches the store (render-path write-storm law) */
  qtRemain--;if(qtRemain>0){el.textContent='0:'+(qtRemain<10?'0':'')+qtRemain}
  else{clearInterval(assessQTimer);assessQTimer=null;el.style.display='none';var ng=document.getElementById('qNudge');if(ng)ng.style.display=''}},1000);}
  on('assessPrev',function(){assessStep=Math.max(1,assessStep-1);bdRenderAssess()});
  on('assessRetake',function(){assessHistIdx=null;assessStep=1;data.assessment={answers:{},scores:{},completedAt:null};saveData();bdRenderAssess()});
  on('assessBackLatest',function(){assessHistIdx=null;bdRenderAssess()});
