  function boardDefs(){return '<defs>'
  +'<filter id="bgrain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed="5" result="n"/><feColorMatrix in="n" type="matrix" values="0 0 0 0 0.36 0 0 0 0 0.31 0 0 0 0 0.24 0 0 0 0.05 0"/><feComposite operator="over" in2="SourceGraphic"/></filter>'
  +'<filter id="weave" x="0" y="0" width="100%" height="100%"><feTurbulence type="turbulence" baseFrequency="0.012 0.11" numOctaves="2" seed="8" result="n"/><feColorMatrix in="n" type="matrix" values="0 0 0 0 0.30 0 0 0 0 0.26 0 0 0 0 0.20 0 0 0 0.045 0"/><feComposite operator="over" in2="SourceGraphic"/></filter>'
  +'<filter id="cardsh" x="-30%" y="-30%" width="160%" height="160%">'+(V.tex?'':'<feDropShadow dx="0" dy="1" stdDeviation="1.1" flood-color="#1E2530" flood-opacity="0.18"/>')+'<feDropShadow dx="'+V.sh.dx+'" dy="'+V.sh.dy+'" stdDeviation="'+V.sh.bl+'" flood-color="'+V.sh.col+'" flood-opacity="'+V.sh.op+'"/></filter>'
  +'<filter id="pinsh" x="-80%" y="-80%" width="260%" height="260%"><feDropShadow dx="0.8" dy="1.8" stdDeviation="1.4" flood-color="'+V.sh.col+'" flood-opacity="'+V.pinSh+'"/></filter>'
  +'<radialGradient id="vign" cx="50%" cy="46%" r="78%"><stop offset="62%" stop-color="#2A241C" stop-opacity="0"/><stop offset="100%" stop-color="#2A241C" stop-opacity="0.15"/></radialGradient>'
  +'<pattern id="dots" width="26" height="26" patternUnits="userSpaceOnUse"><circle cx="13" cy="13" r="1.05" fill="#1E2530" opacity="0.08"/></pattern>'
  +'<linearGradient id="toplight" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFFFFF" stop-opacity="0.45"/><stop offset="1" stop-color="#FFFFFF" stop-opacity="0"/></linearGradient>' 
  +'</defs>'}

  function boardSurface(Wd,Ht){var h='<rect width="'+Wd+'" height="'+Ht+'" rx="'+V.rx+'" fill="'+BOARD+'"/>';
  if(V.tex){h+='<rect width="'+Wd+'" height="'+Ht+'" fill="'+BOARD+'" filter="url(#weave)" opacity="0.9"/>';
  h+='<rect width="'+Wd+'" height="'+Ht+'" fill="'+BOARD+'" filter="url(#bgrain)" opacity="0.7"/>';
  h+='<rect width="'+Wd+'" height="'+Ht+'" fill="url(#vign)"/>';
  h+='<rect x="16" y="16" width="'+(Wd-32)+'" height="'+(Ht-32)+'" fill="none" stroke="'+INK+'" stroke-width="3"/>';
  h+='<rect x="28" y="28" width="'+(Wd-56)+'" height="'+(Ht-56)+'" fill="none" stroke="'+INK+'" stroke-width="0.8" opacity="0.55"/>';}
  else{h+='<rect width="'+Wd+'" height="'+Ht+'" rx="'+V.rx+'" fill="url(#dots)"/>';
  h+='<rect width="'+Wd+'" height="260" rx="'+V.rx+'" fill="url(#toplight)"/>';
  h+='<rect x="16" y="16" width="'+(Wd-32)+'" height="'+(Ht-32)+'" rx="10" fill="none" stroke="rgba(30,37,48,0.30)" stroke-width="1.5"/>';
  [[30,30],[Wd-30,30],[30,Ht-30],[Wd-30,Ht-30]].forEach(function(p){h+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="2.6" fill="rgba(30,37,48,0.28)"/><circle cx="'+(p[0]-0.8)+'" cy="'+(p[1]-0.8)+'" r="0.8" fill="#FFFFFF" opacity="0.5"/>'});}
  return h}

