  function flipOpen(fromRect){
  var bg=document.getElementById('focusBg'),card=document.getElementById('focusCard'),inner=document.getElementById('focusInner');
  if(!fromRect||reducedMotion()){inner.style.opacity=1;bg.classList.add('open');return}
  inner.style.transition='none';inner.style.opacity=0;
  bg.classList.add('open');
  requestAnimationFrame(function(){
  var to=card.getBoundingClientRect();
  if(!to||!to.width){inner.style.opacity=1;return}
  card.style.transformOrigin='top left';card.style.transition='none';
  card.style.transform='translate('+(fromRect.left-to.left)+'px,'+(fromRect.top-to.top)+'px) scale('+(fromRect.width/to.width)+','+(fromRect.height/to.height)+')';
  void card.offsetWidth;
  card.style.transition='transform .42s cubic-bezier(.3,1,.3,1)';
  card.style.transform='';
  inner.style.transition='opacity .26s ease .14s';inner.style.opacity=1;
  setTimeout(function(){card.style.transition='';card.style.transformOrigin=''},450);
  });
  }

