  function buildAssessPrompt(){
  var p='You are the assessment engine inside a reflective practice tool for ethical decision-making. The user has worked through real ethical situations from their own life, writing answers at each step. Your job is to read everything they wrote and produce (1) calibrated scores on five dimensions of ethical decision-making style, and (2) a written profile.\n\n';
  p+='The five dimensions, each scored 0\u2013100. Score from evidence of how this person actually reasons \u2014 never from vocabulary alone. 0 and 100 are the poles; 50 means balanced or insufficient evidence.\n\n';
  p+='1. OUTCOMES (0) vs PRINCIPLES (100). Does their reasoning run on consequences \u2014 who gets hurt, what it costs, how things land \u2014 or on rules, lines, duties, and what they owe? Look at where their reasoning does its real work, especially in the case against their own instinct: which considerations actually move their conclusions, not which words appear.\n';
  p+='2. SELF-SCRUTINIZING (0) vs SELF-TRUSTING (100). When asked what they personally stood to gain, did they genuinely implicate themselves \u2014 name a temptation, an advantage, a bias \u2014 or wave the question off? Honest self-implication scores low; quick dismissal or confident self-clearance scores high. Depth of engagement matters, not length: one sharp admission outweighs a paragraph of throat-clearing.\n';
  p+='3. DECISIVE (0) vs DELIBERATIVE (100). Behavioral, from the timestamps: how long from opening a situation to pressing a verdict? Same-day verdicts lean decisive; weeks lean deliberative. Also weigh whether verdicts moved off the initial instinct after examination \u2014 genuine movement leans mildly deliberative.\n';
  p+='4. BROAD-RESPONSIBILITY (0) vs DEFINED-ROLE (100). In who-this-makes-you, do they own the choice as theirs \u2014 my call, on me, I am responsible \u2014 or locate it outside themselves: policy, hierarchy, not-my-place, what everyone does? Read the stance, not the phrasing; a person can own a choice in reluctant words.\n';
  p+='5. CANDID (0) vs DIPLOMATIC (100). In their verdicts and planned calls, do they move toward direct disclosure \u2014 telling people straight, in the open \u2014 or toward managed timing, softening, and indirect routes? Neither pole is a virtue; you are describing a style.\n\n';
  p+='Scoring discipline: stay near 50 wherever the evidence is thin, and let scores move outward only as evidence accumulates across situations. Never let one situation set an extreme. If a dimension has no evidence at all, score exactly 50.\n\n';
  p+='Weighting: the user\u2019s real situations are the primary evidence. Practice exercises (below, if any) are secondary evidence \u2014 the scenarios are authored by the module and only the answers are the user\u2019s, so they corroborate a lean but never drive one. A lean supported only by practice exercises stays near 50. Timestamps apply to real situations only.\n\n';
  p+='The written profile: second person, addressed to the user. Ground every claim in what they actually wrote \u2014 quote or closely paraphrase their own words as evidence where it sharpens the point. No flattery, no filler, no consultancy language; plain, specific, and direct, like a perceptive colleague who read everything. Format it as ONE text: a lead of 2\u20133 sentences (the overall shape of how they decide, including how often their instinct survived examination), then these four sections, each introduced by its header on its own line exactly as written here \u2014 STRENGTHS: (2\u20133 entries: what they demonstrably do well, each anchored in their answers) BLIND SPOTS: (1\u20133 entries: the question they most reliably underweight, and what it costs them) PATTERNS: (1\u20132 entries: what recurs across situations) FOR NEXT TIME: (one concrete, checkable instruction for their next situation).\n\n';
  p+='Respond with ONLY a JSON object, no markdown fences, no preamble: {"scores":{"outcomes_principles":N,"scrutiny_trust":N,"decisive_deliberative":N,"broad_defined":N,"candor_diplomatic":N},"profile":"<the formatted text>"}\n\n';
  p+='Here are the situations, with the user\u2019s answers verbatim:\n';
  var QL={};for(var sk in SECTIONS){(SECTIONS[sk].qs||[]).forEach(function(q){QL[q.key]=q.label})}
  QL.verdict='The verdict on the instinct (stick / adjust / drop)';QL.theCall='The concrete call';QL.betterPath='Is there a better path?';QL.whatHappened='What happened (look back)';QL.instinctTrust='Did the instinct deserve the trust (look back)';
  data.decisions.forEach(function(dd,di){
  var f=dd.flow||{};
  p+='\n--- Situation '+(di+1)+': '+(dd.title||'Untitled')+' ('+(dd.category||'uncategorized')+') ---\n';
  p+='Opened: '+new Date(dd.createdAt||0).toISOString().slice(0,10);
  if(f.verdictAt)p+=' \u00B7 First verdict pressed: '+new Date(f.verdictAt).toISOString().slice(0,10)+' ('+Math.round(((f.verdictAt-(dd.createdAt||f.verdictAt))/86400000)*10)/10+' days after opening)';
  p+='\n';
  for(var qk in f){if(qk==='verdictAt'||!f[qk]||typeof f[qk]!=='string')continue;
  p+=(QL[qk]||qk)+': '+f[qk]+'\n'}
  });
  var drx=[];DRILLS.forEach(function(dr){var rec=(data.drills||{})[dr.id];if(rec&&(rec.instinct||rec.caseAgainst||rec.verdict))drx.push({dr:dr,rec:rec})});
  if(drx.length){
  p+='\n=== Practice exercises (secondary evidence \u2014 weigh these lightly) ===\n';
  drx.forEach(function(x,xi){
  p+='\n--- Exercise '+(xi+1)+': '+x.dr.title+' ---\n';
  p+='Scenario (authored by the module): '+x.dr.scenario+'\n';
  if(x.rec.instinct)p+='Their instinct: '+x.rec.instinct+'\n';
  if(x.rec.caseAgainst)p+='Their case against it: '+x.rec.caseAgainst+'\n';
  if(x.rec.verdict)p+='Their verdict on the instinct: '+x.rec.verdict+'\n';
  });
  }
  return p;
  }

  function styleContext(){
  var out='';
  var wl=getWatchLens();
  if(wl)out+='\nTHEIR STYLE WATCH-LENS (self-assessment prediction): '+wl.label+' \u2014 '+wl.why+'.';
  var verd=0,stuck=0;
  for(var i=0;i<data.decisions.length;i++){var fv=data.decisions[i].flow||{};if(fv.verdict){verd++;if(fv.verdict==='stick')stuck++}}
  if(verd>=2)out+='\nTRACK RECORD: their instinct survived the lenses unchanged in '+stuck+' of '+verd+' tested situations.';
  var br=getBreakerLens();
  if(br)out+='\nWHAT BREAKS IT: in their look backs, '+br.label+' is the lens that catches their instinct ('+br.n+' of '+br.total+').';
  return out;
  }

  function rt(t){return THREAD_ROUTES[t[0]+'>'+t[1]]=THREAD_ROUTES[t[0]+'>'+t[1]]||{so:0,to:0,lane:0}}

  function cardByKey(k){for(var i=0;i<CARDS.length;i++)if(CARDS[i].key===k)return CARDS[i];return null}

  function spread(list,midOf,span){list.sort(function(p,q){return midOf(p)-midOf(q)});
  var n=list.length,step=Math.min(26,(span-24)/Math.max(n,1));
  return list.map(function(t,i){return (i-(n-1)/2)*step})}

