  var iw=(typeof window!=='undefined'&&window.innerWidth)||1500;
  var z=(window.UI&&UI.zoom)||1;   /* PORTED-IN: the shell owns the zoom. */
  if(typeof currentPage!=='undefined'&&currentPage==='detail'){
  /* R2: surfaces beside drawers use pure monotone window thresholds */
  return iw>=1320*z?'wide':(iw>=716*z?'mid':'narrow');}
  var lay=Math.min((iw-40)/z,iw>=1560?1472:1280);
