  function buildFilesSVG(list,expanded){
  var st={active:[],decided:[],resolved:[]};
  list.forEach(function(d,i){st[decStatus(d)].push(i)});
  var order=st.active.concat(st.decided,st.resolved);
  var showN=expanded?order.length:Math.min(6,order.length);
  var slots=Math.max(6,Math.ceil(showN/3)*3);
  if(expanded)slots=Math.ceil(order.length/3)*3;
  var rows=slots/3;
  var gy0=352,rowH=196;
  var Hf=gy0+rows*rowH+(order.length>6?70:40)+40;
  var s='<svg viewBox="0 0 '+W+' '+Hf+'" xmlns="http://www.w3.org/2000/svg">'+boardDefs();
  s+=boardSurface(W,Hf);
  s+='<line x1="70" y1="308" x2="'+(W-70)+'" y2="308" stroke="'+INK+'" stroke-width="0.8" opacity="'+(V.tex?0.14:0.13)+'"/>';
  s+=filesHeaderCard()+newFolder()+newExercisesFolder();
  var xs=[96,560,1024];
  for(var k=0;k<slots;k++){
  var col=k%3,row=Math.floor(k/3);
  var x=xs[col],y=gy0+row*rowH;
  if(k<showN)s+=folderSVG(list[order[k]],order[k],x,y);
  else s+=ghostFolder(x,y);
  }
  if(order.length>6)s+=filesPullTab(order.length,expanded,gy0+rows*rowH+8);
  s+='</svg>';return s}

