  s2+='<text x="'+cx+'" y="'+(y+47)+'" font-family="Cormorant Garamond" font-size="22" letter-spacing="4" text-anchor="middle" fill="'+INK+'">THE ETHICS FILES</text>';
  s2+='<text x="'+cx+'" y="'+(y+63)+'" font-family="Cormorant Garamond" font-size="13" text-anchor="middle" fill="'+INK+'" opacity="0.85">Every situation you have opened, active and resolved</text>';
  s2+=pin(cx,y+6,V.keypin,false);
  y+=96;
  s2+='<g id="newFolder" class="bd-click" style="cursor:pointer"><g filter="url(#cardsh)">'+bdCardRect(cx-190,y,380,64,V.white,false)+'</g>'+railBarV(cx-190,y,64,GOLDT,4);
  s2+='<text x="'+cx+'" y="'+(y+28)+'" font-family="DM Mono" font-size="12" letter-spacing="2" text-anchor="middle" fill="'+GOLDT+'">START WORKING THROUGH A NEW SITUATION</text>';
  s2+='<text x="'+cx+'" y="'+(y+50)+'" font-family="Cormorant Garamond" font-size="17" text-anchor="middle" fill="'+INK+'" opacity="0.85">open a fresh file \u2192</text></g>';
  y+=94;
  s2+='<g id="newExercises" class="bd-click" style="cursor:pointer"><g filter="url(#cardsh)">'+bdCardRect(cx-190,y,380,64,V.white,false)+'</g>'+railBarV(cx-190,y,64,V.p1,4); /* M-3 fix (ruled July 30): the drills entry exists at every tier, not only wide */
  s2+='<text x="'+cx+'" y="'+(y+28)+'" font-family="DM Mono" font-size="12" letter-spacing="2" text-anchor="middle" fill="'+V.p1+'">ETHICAL EXERCISES</text>';
  s2+='<text x="'+cx+'" y="'+(y+50)+'" font-family="Cormorant Garamond" font-size="17" text-anchor="middle" fill="'+INK+'" opacity="0.85">practice scenarios \u2192</text></g>';
  y+=78;
  var st={active:[],decided:[],resolved:[]};
