  function getWatchLens(){
  var a=data.assessment;if(!a||!a.scores||!a.completedAt)return null;
  var s=a.scores,c=[];
  if(s.scrutiny_trust>=60)c.push({sec:'stake',label:'Your Stake',mag:Math.abs(s.scrutiny_trust-50),why:'You trust your own read quickly, so Your Stake is the lens you are most likely to rush past'});
  if(s.outcomes_principles>=60)c.push({sec:'people',label:'The People',mag:Math.abs(s.outcomes_principles-50),why:'Your answers lean toward principle, so The People is the lens you are most likely to rush past'});
  if(s.outcomes_principles<=40)c.push({sec:'principle',label:'The Principle',mag:Math.abs(s.outcomes_principles-50),why:'your answers lean toward outcomes, so The Principle is the lens you are most likely to rush past'});
  if(s.broad_defined>=60)c.push({sec:'identity',label:'Who This Makes You',mag:Math.abs(s.broad_defined-50),why:'You keep to a defined role, so Who This Makes You is the lens you are most likely to rush past'});
  if(!c.length)return null;
  c.sort(function(x,y){return y.mag-x.mag});
  return c[0];
  }

  function getBreakerLens(){
  // Evidence from look-back chips: which lens actually catches the instinct.
  // Real button presses only \u2014 no text-volume guessing.
  var count={stake:0,people:0,principle:0,identity:0},total=0;
  for(var i=0;i<data.decisions.length;i++){
  var f=data.decisions[i].flow||{};
  if(f.brokeLens&&f.brokeLens!=='held'){count[f.brokeLens]++;total++}
  }
  if(data.drills){for(var dk in data.drills){var drx=data.drills[dk];if(drx.brokeLens&&drx.brokeLens!=='held'){count[drx.brokeLens]++;total++}}}
  var top=null,tn=0;
  for(var k in count){if(count[k]>tn){tn=count[k];top=k}}
  if(!top||tn<2)return null; // need at least 2 look backs pointing the same way
  var label={stake:'Your Stake',people:'The People',principle:'The Principle',identity:'Who This Makes You'}[top];
  return {sec:top,label:label,n:tn,total:total};
  }

