  if(a&&b){h+='<path class="t-proc" d="'+pl.d+'" fill="none" stroke="'+INK+'" stroke-width="1.3" opacity="0.34"/>';if(pl.mid)h+=pl.mid+' fill="'+INK+'" opacity="0.42"/>';return}
